describe('legacy snack bar no-op open notification', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [MatLegacySnackBarModule],
      providers: [LEGACY_NOOP_ANIMATIONS],
    });
  });

  it('notifies a caller who subscribes immediately after open returns', fakeAsync(() => {
    const ref = TestBed.inject(MatLegacySnackBar).open('message');
    let notifications = 0;
    let completed = false;
    ref.afterOpened().subscribe({next: () => notifications++, complete: () => completed = true});
    expect(notifications).toBe(0);
    expect(completed).toBeFalse();
    tick();
    expect(notifications).toBe(1);
    expect(completed).toBeTrue();
    ref.dismiss();
    tick();
  }));

  it('does not notify a snack bar dismissed before its enter completes', fakeAsync(() => {
    const ref = TestBed.inject(MatLegacySnackBar).open('message');
    let notifications = 0;
    ref.afterOpened().subscribe(() => notifications++);
    ref.dismiss();
    tick();
    expect(notifications).toBe(0);
  }));

  it('only notifies the replacement when replaced before enter completes', fakeAsync(() => {
    const snackBar = TestBed.inject(MatLegacySnackBar);
    const previous = snackBar.open('previous');
    let previousNotifications = 0;
    previous.afterOpened().subscribe(() => previousNotifications++);
    const next = snackBar.open('next');
    let nextNotifications = 0;
    next.afterOpened().subscribe(() => nextNotifications++);
    tick();
    expect(previousNotifications).toBe(0);
    expect(nextNotifications).toBe(1);
    next.dismiss();
    tick();
  }));

  it('does not notify after the container is destroyed', fakeAsync(() => {
    const ref = TestBed.inject(MatLegacySnackBar).open('message');
    let notifications = 0;
    ref.afterOpened().subscribe(() => notifications++);
    ref.containerInstance.ngOnDestroy();
    tick();
    expect(notifications).toBe(0);
  }));

  it('still starts the duration timer when opening completes', fakeAsync(() => {
    const ref = TestBed.inject(MatLegacySnackBar).open('message', '', {duration: 100});
    let opened = 0;
    let dismissed = 0;
    ref.afterOpened().subscribe(() => opened++);
    ref.afterDismissed().subscribe(() => dismissed++);
    tick();
    expect(opened).toBe(1);
    tick(100);
    expect(dismissed).toBe(1);
  }));
});


describe('legacy snack bar reentrant no-op notification', () => {
  beforeEach(() => TestBed.configureTestingModule({
    imports: [MatLegacySnackBarModule],
    providers: [LEGACY_NOOP_ANIMATIONS],
  }));

  it('allows an afterOpened subscriber to dismiss immediately', fakeAsync(() => {
    const ref = TestBed.inject(MatLegacySnackBar).open('message');
    let opened = 0;
    let dismissed = 0;
    ref.afterDismissed().subscribe(() => dismissed++);
    ref.afterOpened().subscribe(() => { opened++; ref.dismiss(); });
    tick();
    expect(opened).toBe(1);
    expect(dismissed).toBe(1);
  }));

  it('allows an afterOpened subscriber to replace the snack bar', fakeAsync(() => {
    const snackBar = TestBed.inject(MatLegacySnackBar);
    const previous = snackBar.open('previous');
    let previousOpened = 0;
    let nextOpened = 0;
    let next: MatLegacySnackBarRef<LegacySimpleSnackBar>;
    previous.afterOpened().subscribe(() => {
      previousOpened++;
      next = snackBar.open('next');
      next.afterOpened().subscribe(() => nextOpened++);
    });
    tick();
    expect(previousOpened).toBe(1);
    expect(nextOpened).toBe(1);
    next!.dismiss();
    tick();
  }));
});

let captured: Array<{cdk: CdkDialogRef; optional: CdkDialogRef | null; legacy: MatLegacyDialogRef<any>}> = [];

@Directive({standalone: false, selector: '[dialogRefProbe]'})
class DialogRefProbe {
  constructor() {
    captured.push({
      cdk: injectToken(CdkDialogRef),
      optional: injectToken(CdkDialogRef, {optional: true}),
      legacy: injectToken(MatLegacyDialogRef),
    });
  }
}

@Component({standalone: false, template: '<button dialogRefProbe>dialog</button>'})
class DialogRefContent {}

@Component({
  standalone: false,
  template: '<button id="origin">origin</button><ng-template><button dialogRefProbe>template</button></ng-template>',
})
class DialogRefHost {
  @ViewChild(TemplateRef) template!: TemplateRef<any>;
}

describe('legacy dialog content reference injection', () => {
  beforeEach(() => {
    captured = [];
    TestBed.configureTestingModule({
      declarations: [DialogRefProbe, DialogRefContent, DialogRefHost],
      imports: [MatLegacyDialogModule],
      providers: [LEGACY_NOOP_ANIMATIONS],
    });
  });

  for (const kind of ['component', 'template'] as const) {
    for (const method of ['legacy', 'cdk'] as const) {
      it(`retains ${kind} reference identity and ${method} close behavior`, fakeAsync(() => {
        const fixture = TestBed.createComponent(DialogRefHost);
        fixture.detectChanges();
        const origin = fixture.nativeElement.querySelector('#origin') as HTMLElement;
        origin.focus();
        const dialog = TestBed.inject(MatLegacyDialog);
        const ref = kind === 'component' ? dialog.open(DialogRefContent) :
          dialog.open(fixture.componentInstance.template);
        fixture.detectChanges();
        tick(250);
        fixture.detectChanges();

        const pair = captured[0];
        expect(pair.legacy).toBe(ref);
        expect(pair.cdk).toBeTruthy();
        expect(pair.optional).toBe(pair.cdk);
        expect(pair.cdk).not.toBe(pair.legacy as unknown as CdkDialogRef);
        const before: unknown[] = [];
        const after: unknown[] = [];
        ref.beforeClosed().subscribe(value => before.push(value));
        ref.afterClosed().subscribe(value => after.push(value));
        pair[method].close(`${method}-result`);
        fixture.detectChanges();
        tick(500);
        fixture.detectChanges();

        const result = method === 'legacy' ? 'legacy-result' : undefined;
        expect(before).toEqual([result]);
        expect(after).toEqual([result]);
        expect(dialog.openDialogs.length).toBe(0);
        expect(document.activeElement).toBe(origin);
        fixture.destroy();
      }));
    }
  }

  it('cleans up a CDK-closed nested child and a legacy-closed parent', fakeAsync(() => {
    const fixture = TestBed.createComponent(DialogRefHost);
    fixture.detectChanges();
    const origin = fixture.nativeElement.querySelector('#origin') as HTMLElement;
    origin.focus();
    const dialog = TestBed.inject(MatLegacyDialog);
    const outer = dialog.open(DialogRefContent);
    fixture.detectChanges();
    tick(250);
    const inner = dialog.open(DialogRefContent);
    fixture.detectChanges();
    tick(250);
    expect(captured.length).toBe(2);
    let innerAfter = 0;
    let outerAfter = 0;
    inner.afterClosed().subscribe(() => innerAfter++);
    outer.afterClosed().subscribe(() => outerAfter++);
    captured[1].cdk.close('child');
    fixture.detectChanges();
    tick(500);
    fixture.detectChanges();
    expect(dialog.openDialogs.length).toBe(1);
    expect(innerAfter).toBe(1);
    expect(outerAfter).toBe(0);
    outer.close('outer');
    fixture.detectChanges();
    tick(500);
    fixture.detectChanges();
    expect(dialog.openDialogs.length).toBe(0);
    expect(innerAfter).toBe(1);
    expect(outerAfter).toBe(1);
    expect(document.activeElement).toBe(origin);
    fixture.destroy();
  }));
});

