  expect(calls).toBe(1);
  expect(instance.trigger.menu).toBe(instance.second);
  expect(instance.trigger.menuOpen).toBeFalse();
  expect(overlayContainerElement.querySelectorAll('.mat-menu-panel').length).toBe(0);
  fixture.destroy();
  tick(500);
}));

